def compute(vars):
    threshold = 4000
    qualifying_years = [
        vars["v1"] > threshold,
        vars["v2"] > threshold,
        vars["v3"] > threshold,
        vars["v4"] > threshold,
        vars["v5"] > threshold,
    ]
    count = sum(qualifying_years)

    return {
        "value": count,
        "trace": {
            "threshold": threshold,
            "qualifying_years": qualifying_years,
            "output_meta": {
                "currency": None,
                "scale": "years",
                "unit": "years"
            }
        }
    }
